const raw = String($json.text ?? $json.output ?? '');

// Strip code fences / stray text and grab the JSON object
let cleaned = raw.replace(/```json|```/gi, '').trim();
const start = cleaned.indexOf('{');
const end = cleaned.lastIndexOf('}');
if (start !== -1 && end !== -1) {
  cleaned = cleaned.slice(start, end + 1);
}

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    important: true,
    category: 'other',
    summary: 'Failed to parse AI output: ' + raw.slice(0, 200),
    reply: ''
  };
}

// Original email data from the trigger
const email = $('Email Trigger (IMAP)').item.json;
const fromRaw = String(email.from ?? '');
const match = fromRaw.match(/<([^>]+)>/);
const senderEmail = (match ? match[1] : fromRaw).trim();

// Escape text for Telegram HTML mode
const esc = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

const important = parsed.important === true || String(parsed.important).toLowerCase() === 'true';

return {
  json: {
    important,
    category: String(parsed.category ?? 'other'),
    summary: String(parsed.summary ?? ''),
    reply: String(parsed.reply ?? ''),
    senderEmail,
    senderRaw: fromRaw,
    originalSubject: String(email.subject ?? ''),
    tgSender: esc(senderEmail),
    tgSubject: esc(email.subject ?? ''),
    tgCategory: esc(parsed.category ?? 'other'),
    tgSummary: esc(parsed.summary ?? ''),
    tgReply: esc(parsed.reply ?? '')
  }
};
